const total = ctx.words.length;
const latest = Math.max(ctx.duration - 0.6, 0);
const cue = (fraction) => Math.min(ctx.at(Math.min(Math.round(fraction * (total - 1)), total - 1)), latest);
const wordsFrom = (start, count) => ctx.words.slice(start, start + count).map((word) => word.text).join(" ");
const clean = (text, limit) => text.replace(/[^\p{L}\p{N}]/gu, "").slice(0, limit);
const LINES = ["const nums = [1, 2, 3];", "const twice = nums.map((n) => n * 2);", "console.log(twice);"];
const IDLE_OPACITY = 0.7;
const caption = document.createElement("p");
caption.className = "mo-caption mo-c-label";
caption.textContent = "script.js";
const editor = document.createElement("div");
editor.className = "mo-code mo-c-editor";
const body = document.createElement("div");
body.className = "mo-c-body";
const highlight = document.createElement("div");
highlight.className = "mo-c-highlight";
body.append(highlight);
const lines = LINES.map((text, index) => {
  const line = document.createElement("div");
  line.className = "mo-c-line";
  const number = document.createElement("span");
  number.className = "mo-c-number";
  number.textContent = String(index + 1);
  line.append(number, document.createTextNode(text));
  body.append(line);
  return line;
});
editor.append(body);
ctx.root.append(caption, editor);
const bodyTop = body.getBoundingClientRect().top;
const metrics = lines.map((line) => {
  const box = line.getBoundingClientRect();
  return { top: box.top - bodyTop, height: box.height };
});
gsap.set(highlight, { y: metrics[0].top, height: metrics[0].height, opacity: 0 });
gsap.set(lines, { opacity: IDLE_OPACITY });
ctx.timeline.from(editor, { opacity: 0, y: 40, duration: 0.5, ease: "power3.out" }, 0);
[0.1, 0.5, 0.85].forEach((fraction, index) => {
  const start = cue(fraction);
  if (index === 0) {
    ctx.timeline.to(highlight, { opacity: 1, duration: 0.3 }, start);
  } else {
    ctx.timeline.to(
      highlight,
      { y: metrics[index].top, height: metrics[index].height, duration: 0.4, ease: "power2.inOut" },
      start,
    );
    ctx.timeline.to(lines[index - 1], { opacity: IDLE_OPACITY, duration: 0.3 }, start);
  }
  ctx.timeline.to(lines[index], { opacity: 1, duration: 0.3 }, start);
});

