.mo-s-{{sceneId}} {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.mo-s-{{sceneId}} .mo-c-label {
  margin-bottom: calc(var(--mo-unit) * 3);
  letter-spacing: 0.08em;
}
.mo-s-{{sceneId}} .mo-c-editor {
  position: relative;
  padding: 0;
  overflow: hidden;
}
.mo-s-{{sceneId}} .mo-c-body {
  position: relative;
  padding: calc(var(--mo-unit) * 2.4) 0;
}
.mo-s-{{sceneId}} .mo-c-highlight {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  background: var(--mo-elevated);
  border-left: calc(var(--mo-unit) * 0.6) solid var(--mo-accent);
}
.mo-s-{{sceneId}} .mo-c-line {
  position: relative;
  padding: 0 calc(var(--mo-unit) * 3);
  white-space: pre;
  line-height: 1.7;
}
.mo-s-{{sceneId}} .mo-c-number {
  display: inline-block;
  width: 2ch;
  margin-right: 2ch;
  color: var(--mo-text-secondary);
  text-align: right;
}
